def personal_goals():
    st.markdown("""<div class="churchgate-header"><h1>🎯 Personal Goals & OKRs</h1><p>Set Goals | Track Progress | Align to Strategic Pillars | Drive Your Growth</p></div>""", unsafe_allow_html=True)
    
